package migrator

import (
	"context"
	"errors"
	"fmt"
	"strconv"
)

// ErrCursorNotFound is returned by KVBackend.Get when the requested
// key has no value yet. Callers (Cursor.Get) interpret this as
// "first run, start at offset 0".
var ErrCursorNotFound = errors.New("migrator: cursor not found")

// KVBackend is the minimal interface Cursor needs from a key-value
// store. Production wires it to a NATS JetStream KV bucket via a
// thin adapter; tests pass an in-memory map.
//
// Get returns ErrCursorNotFound when the key has no value (cleanly
// distinguished from a transport error so first-run logic is
// explicit). Put creates-or-replaces.
type KVBackend interface {
	Get(ctx context.Context, key string) ([]byte, error)
	Put(ctx context.Context, key string, value []byte) error
}

// Cursor wraps a KVBackend with the migrator-specific key shape and
// value encoding. Per spec §3.4 the key is "<binary>/<tenant>/<entity>"
// and the value is the legacy integer primary key encoded as ASCII
// decimal — kept human-readable so operators can `nats kv get` a
// bucket and read the cursor without tooling.
type Cursor struct {
	be KVBackend
}

// NewCursor constructs a cursor wrapper. The backend is the only
// dependency — no NATS imports leak into callers' tests.
func NewCursor(be KVBackend) *Cursor {
	return &Cursor{be: be}
}

// Get returns the last successfully-applied legacy PK for the given
// (binary, tenant, entity) triple. The found return distinguishes
// "no cursor yet, start at 0" from "cursor is exactly 0 because of a
// quirk." On a clean first run, returns (0, false, nil).
func (c *Cursor) Get(ctx context.Context, binary, tenant, entity string) (int64, bool, error) {
	if err := validateKeyParts(binary, tenant, entity); err != nil {
		return 0, false, err
	}
	raw, err := c.be.Get(ctx, cursorKey(binary, tenant, entity))
	if errors.Is(err, ErrCursorNotFound) {
		return 0, false, nil
	}
	if err != nil {
		return 0, false, fmt.Errorf("migrator: cursor get: %w", err)
	}
	off, err := strconv.ParseInt(string(raw), 10, 64)
	if err != nil {
		return 0, false, fmt.Errorf("migrator: cursor parse value %q: %w", string(raw), err)
	}
	return off, true, nil
}

// Put records that legacy PK `offset` has been successfully applied
// for the given (binary, tenant, entity) triple. The migrator calls
// this after each successful gRPC apply so a mid-batch crash resumes
// from the next row. Spec §9 ("error handling matrix") relies on the
// invariant that Put runs only on Code=OK from the target RPC.
func (c *Cursor) Put(ctx context.Context, binary, tenant, entity string, offset int64) error {
	if err := validateKeyParts(binary, tenant, entity); err != nil {
		return err
	}
	if err := c.be.Put(ctx, cursorKey(binary, tenant, entity), []byte(strconv.FormatInt(offset, 10))); err != nil {
		return fmt.Errorf("migrator: cursor put: %w", err)
	}
	return nil
}

// cursorKey builds the canonical key shape from spec §3.4. Pinned
// here (and tested) because operators rely on the layout.
func cursorKey(binary, tenant, entity string) string {
	return binary + "/" + tenant + "/" + entity
}

func validateKeyParts(binary, tenant, entity string) error {
	if binary == "" {
		return errors.New("migrator: cursor binary required")
	}
	if tenant == "" {
		return errors.New("migrator: cursor tenant required")
	}
	if entity == "" {
		return errors.New("migrator: cursor entity required")
	}
	return nil
}


