package migrator_test

import (
	"context"
	"errors"
	"strings"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
)

// memBackend is an in-memory migrator.KVBackend used by Cursor tests.
// Real production code passes a JetStreamKV wrapper over a NATS bucket.
type memBackend struct {
	mu sync.Mutex
	kv map[string][]byte
}

func newMemBackend() *memBackend {
	return &memBackend{kv: map[string][]byte{}}
}

func (m *memBackend) Get(_ context.Context, key string) ([]byte, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	v, ok := m.kv[key]
	if !ok {
		return nil, migrator.ErrCursorNotFound
	}
	return append([]byte(nil), v...), nil
}

func (m *memBackend) Put(_ context.Context, key string, value []byte) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.kv[key] = append([]byte(nil), value...)
	return nil
}

func TestCursor_GetReturnsZeroAndFalseOnFirstRun(t *testing.T) {
	c := migrator.NewCursor(newMemBackend())
	off, found, err := c.Get(context.Background(), "migrator-identity", "42", "users")
	require.NoError(t, err)
	require.False(t, found)
	require.Equal(t, int64(0), off)
}

func TestCursor_PutThenGetRoundTrips(t *testing.T) {
	c := migrator.NewCursor(newMemBackend())
	ctx := context.Background()

	require.NoError(t, c.Put(ctx, "migrator-identity", "42", "users", 12345))
	off, found, err := c.Get(ctx, "migrator-identity", "42", "users")
	require.NoError(t, err)
	require.True(t, found)
	require.Equal(t, int64(12345), off)
}

func TestCursor_KeysAreScopedByBinaryAndTenantAndEntity(t *testing.T) {
	be := newMemBackend()
	c := migrator.NewCursor(be)
	ctx := context.Background()

	require.NoError(t, c.Put(ctx, "migrator-identity", "42", "users", 1))
	require.NoError(t, c.Put(ctx, "migrator-org", "42", "tenants", 2))
	require.NoError(t, c.Put(ctx, "migrator-identity", "99", "users", 3))

	off1, _, _ := c.Get(ctx, "migrator-identity", "42", "users")
	off2, _, _ := c.Get(ctx, "migrator-org", "42", "tenants")
	off3, _, _ := c.Get(ctx, "migrator-identity", "99", "users")

	require.Equal(t, int64(1), off1)
	require.Equal(t, int64(2), off2)
	require.Equal(t, int64(3), off3)
}

func TestCursor_KeyShapeMatchesSpec(t *testing.T) {
	be := newMemBackend()
	c := migrator.NewCursor(be)
	require.NoError(t, c.Put(context.Background(), "migrator-identity", "42", "users", 7))

	// The exact shape is part of the spec (§3.4): "<binary>/<tenant>/<entity>".
	// Operators may grep / dump the bucket; renaming is a breaking change.
	be.mu.Lock()
	defer be.mu.Unlock()
	_, ok := be.kv["migrator-identity/42/users"]
	require.True(t, ok, "key shape must be <binary>/<tenant>/<entity>")
}

func TestCursor_PutValueIsHumanReadableASCII(t *testing.T) {
	be := newMemBackend()
	c := migrator.NewCursor(be)
	require.NoError(t, c.Put(context.Background(), "migrator-org", "42", "tenants", 12345))

	be.mu.Lock()
	defer be.mu.Unlock()
	require.Equal(t, "12345", string(be.kv["migrator-org/42/tenants"]),
		"value must be ASCII decimal so operators can `nats kv get` and read it")
}

func TestCursor_RejectsEmptyComponents(t *testing.T) {
	c := migrator.NewCursor(newMemBackend())
	ctx := context.Background()

	cases := []struct{ binary, tenant, entity string }{
		{"", "42", "users"},
		{"migrator-identity", "", "users"},
		{"migrator-identity", "42", ""},
	}
	for _, tc := range cases {
		err := c.Put(ctx, tc.binary, tc.tenant, tc.entity, 1)
		require.Errorf(t, err, "empty component (%q,%q,%q) must be rejected",
			tc.binary, tc.tenant, tc.entity)
	}
}

func TestCursor_GetSurfacesMalformedValue(t *testing.T) {
	be := newMemBackend()
	be.kv["migrator-identity/42/users"] = []byte("not-a-number")
	c := migrator.NewCursor(be)

	_, _, err := c.Get(context.Background(), "migrator-identity", "42", "users")
	require.Error(t, err)
	require.Contains(t, strings.ToLower(err.Error()), "parse")
}

func TestCursor_PropagatesBackendError(t *testing.T) {
	failing := &failingBackend{getErr: errors.New("nats unavailable")}
	c := migrator.NewCursor(failing)

	_, _, err := c.Get(context.Background(), "migrator-identity", "42", "users")
	require.Error(t, err)
	require.Contains(t, err.Error(), "nats unavailable")
}

type failingBackend struct {
	getErr error
	putErr error
}

func (f *failingBackend) Get(context.Context, string) ([]byte, error) { return nil, f.getErr }
func (f *failingBackend) Put(context.Context, string, []byte) error    { return f.putErr }


