package migrator_test

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/metric/metricdata"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
)

// newTestMetrics returns a Metrics wired to a manual reader so tests
// can collect and assert on emitted measurements.
func newTestMetrics(t *testing.T) (*migrator.Metrics, *metric.ManualReader) {
	t.Helper()
	rdr := metric.NewManualReader()
	mp := metric.NewMeterProvider(metric.WithReader(rdr))
	t.Cleanup(func() { _ = mp.Shutdown(context.Background()) })

	m, err := migrator.NewMetrics(mp.Meter("migrator-test"))
	require.NoError(t, err)
	return m, rdr
}

// findMetric scans collected ResourceMetrics for an instrument by name.
// Returns the metricdata.Metrics or fails the test.
func findMetric(t *testing.T, rm metricdata.ResourceMetrics, name string) metricdata.Metrics {
	t.Helper()
	for _, sm := range rm.ScopeMetrics {
		for _, m := range sm.Metrics {
			if m.Name == name {
				return m
			}
		}
	}
	t.Fatalf("metric %q not found in collected ResourceMetrics", name)
	return metricdata.Metrics{}
}

func TestMetrics_RowsPlannedIncrements(t *testing.T) {
	m, rdr := newTestMetrics(t)
	ctx := context.Background()

	m.RowsPlanned(ctx, "42", "users")
	m.RowsPlanned(ctx, "42", "users")
	m.RowsPlanned(ctx, "42", "tenants")

	var rm metricdata.ResourceMetrics
	require.NoError(t, rdr.Collect(ctx, &rm))

	got := findMetric(t, rm, "migrator_rows_planned_total")
	sum := got.Data.(metricdata.Sum[int64])
	require.Len(t, sum.DataPoints, 2, "two distinct (tenant,entity) keys → two points")
	for _, dp := range sum.DataPoints {
		ent, _ := dp.Attributes.Value("entity")
		switch ent.AsString() {
		case "users":
			require.Equal(t, int64(2), dp.Value)
		case "tenants":
			require.Equal(t, int64(1), dp.Value)
		default:
			t.Fatalf("unexpected entity %q", ent.AsString())
		}
	}
}

func TestMetrics_RowsAppliedCarriesResultLabel(t *testing.T) {
	m, rdr := newTestMetrics(t)
	ctx := context.Background()

	m.RowsApplied(ctx, "42", "users", "created")
	m.RowsApplied(ctx, "42", "users", "created")
	m.RowsApplied(ctx, "42", "users", "upserted")

	var rm metricdata.ResourceMetrics
	require.NoError(t, rdr.Collect(ctx, &rm))

	got := findMetric(t, rm, "migrator_rows_applied_total")
	sum := got.Data.(metricdata.Sum[int64])
	require.Len(t, sum.DataPoints, 2)

	totals := map[string]int64{}
	for _, dp := range sum.DataPoints {
		v, _ := dp.Attributes.Value("result")
		totals[v.AsString()] = dp.Value
	}
	require.Equal(t, int64(2), totals["created"])
	require.Equal(t, int64(1), totals["upserted"])
}

func TestMetrics_ApplyDurationRecordsHistogram(t *testing.T) {
	m, rdr := newTestMetrics(t)
	ctx := context.Background()

	m.RecordApplyDuration(ctx, "42", "users", 150*time.Millisecond)
	m.RecordApplyDuration(ctx, "42", "users", 250*time.Millisecond)

	var rm metricdata.ResourceMetrics
	require.NoError(t, rdr.Collect(ctx, &rm))

	got := findMetric(t, rm, "migrator_apply_duration_seconds")
	hist := got.Data.(metricdata.Histogram[float64])
	require.Len(t, hist.DataPoints, 1)
	require.Equal(t, uint64(2), hist.DataPoints[0].Count)
	require.InDelta(t, 0.4, hist.DataPoints[0].Sum, 1e-9)
}

func TestMetrics_LagRowsSetsGauge(t *testing.T) {
	m, rdr := newTestMetrics(t)
	ctx := context.Background()

	m.SetLagRows(ctx, "42", "users", 100)
	m.SetLagRows(ctx, "42", "users", 95) // overwrite
	m.SetLagRows(ctx, "42", "tenants", 1)

	var rm metricdata.ResourceMetrics
	require.NoError(t, rdr.Collect(ctx, &rm))

	got := findMetric(t, rm, "migrator_lag_rows")
	g := got.Data.(metricdata.Gauge[int64])
	require.Len(t, g.DataPoints, 2)

	per := map[string]int64{}
	for _, dp := range g.DataPoints {
		v, _ := dp.Attributes.Value("entity")
		per[v.AsString()] = dp.Value
	}
	require.Equal(t, int64(95), per["users"], "Set must overwrite, not accumulate")
	require.Equal(t, int64(1), per["tenants"])
}

func TestMetrics_RejectionsCarryErrorCode(t *testing.T) {
	m, rdr := newTestMetrics(t)
	ctx := context.Background()

	m.RejectionsInc(ctx, "42", "users", "INVALID_ARGUMENT")
	m.RejectionsInc(ctx, "42", "users", "INVALID_ARGUMENT")
	m.RejectionsInc(ctx, "42", "users", "PERMISSION_DENIED")

	var rm metricdata.ResourceMetrics
	require.NoError(t, rdr.Collect(ctx, &rm))

	got := findMetric(t, rm, "migrator_rejections_total")
	sum := got.Data.(metricdata.Sum[int64])
	require.Len(t, sum.DataPoints, 2)

	per := map[string]int64{}
	for _, dp := range sum.DataPoints {
		v, _ := dp.Attributes.Value("error_code")
		per[v.AsString()] = dp.Value
	}
	require.Equal(t, int64(2), per["INVALID_ARGUMENT"])
	require.Equal(t, int64(1), per["PERMISSION_DENIED"])
}

func TestMetrics_TokenRefreshHasNoLabels(t *testing.T) {
	m, rdr := newTestMetrics(t)
	ctx := context.Background()

	m.TokenRefreshInc(ctx)
	m.TokenRefreshInc(ctx)
	m.TokenRefreshInc(ctx)

	var rm metricdata.ResourceMetrics
	require.NoError(t, rdr.Collect(ctx, &rm))

	got := findMetric(t, rm, "migrator_token_refresh_total")
	sum := got.Data.(metricdata.Sum[int64])
	require.Len(t, sum.DataPoints, 1, "no label dimensions → exactly one point")
	require.Equal(t, int64(3), sum.DataPoints[0].Value)
	require.Equal(t, 0, sum.DataPoints[0].Attributes.Len(), "no attributes")
}


