package migrator

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// RejectionEntry is one row appended to the rejection report. The shape
// is JSON-stable — operators write Grafana queries and ad-hoc grep
// scripts against it, so renaming a field is a breaking change.
type RejectionEntry struct {
	LegacyID  string    `json:"legacy_id"`
	Entity    string    `json:"entity"` // "users" / "tenants" / "memberships"
	ErrorCode string    `json:"error_code"`
	ErrorMsg  string    `json:"error_msg"`
	Timestamp time.Time `json:"timestamp"`
}

// Rejection is an append-only JSON Lines writer for rejected migrator
// rows. Each migrator run opens its own file under
// $MIGRATOR_REJECTION_REPORT_DIR/<run-id>.jsonl. Writes are
// goroutine-safe — phase loops may call Write from multiple workers if
// the migrator ever moves to parallel batches.
type Rejection struct {
	mu     sync.Mutex
	f      *os.File
	closed bool
}

// OpenRejection creates dir if needed and opens (or truncates) the
// per-run report file <dir>/<runID>.jsonl. Subsequent Write calls
// append; Close flushes and closes the file. Each migrator process
// should pick a unique runID (typically a UUIDv7 minted at startup).
func OpenRejection(dir, runID string) (*Rejection, error) {
	if runID == "" {
		return nil, errors.New("migrator: runID required")
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("migrator: create rejection dir: %w", err)
	}
	path := filepath.Join(dir, runID+".jsonl")
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return nil, fmt.Errorf("migrator: open rejection file: %w", err)
	}
	return &Rejection{f: f}, nil
}

// Write appends one JSON Lines record. Returns an error if the writer
// has already been closed or if the underlying file write fails.
func (r *Rejection) Write(entry RejectionEntry) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return errors.New("migrator: write to closed Rejection")
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("migrator: marshal rejection: %w", err)
	}
	line = append(line, '\n')
	if _, err := r.f.Write(line); err != nil {
		return fmt.Errorf("migrator: write rejection: %w", err)
	}
	return nil
}

// Close flushes and closes the file. Idempotent.
func (r *Rejection) Close() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return nil
	}
	r.closed = true
	return r.f.Close()
}


