package migrator

import (
	"context"
	"sync"
	"sync/atomic"
	"time"

	"golang.org/x/oauth2"
)

// safetyMargin proactively refreshes a token this long before its
// stated Expiry. Bounds the worst-case clock skew between the migrator
// process and Keycloak, plus the ~1-2s round-trip cost of the refresh
// call itself, so a long-running batch loop never makes a request with
// a token that will expire mid-flight.
const safetyMargin = 30 * time.Second

// Token caches a service-account access token from Keycloak's
// client_credentials grant and refreshes it proactively before expiry.
// Goroutine-safe — concurrent Token() calls coalesce around a single
// mint via the lock.
//
// The wrapped TokenSource is typically a
// `clientcredentials.Config{...}.TokenSource(ctx)` against the
// omnicore-migrator client. Tests pass a fake source.
type Token struct {
	src oauth2.TokenSource
	now func() time.Time

	mu  sync.Mutex
	cur *oauth2.Token

	// Atomic so RefreshCount() is lock-free. Updated under mu when a
	// fresh mint succeeds.
	refreshes atomic.Int64
}

// NewToken wraps src with a 30s-safety-margin cache backed by the real
// wall clock. Use NewTokenWithClock from tests that need to control
// time.
func NewToken(src oauth2.TokenSource) *Token {
	return NewTokenWithClock(src, time.Now)
}

// NewTokenWithClock is the test seam — pass a custom clock to drive
// the safety-margin logic deterministically.
func NewTokenWithClock(src oauth2.TokenSource, now func() time.Time) *Token {
	return &Token{src: src, now: now}
}

// Token returns a non-expiring access token. Subsequent calls reuse
// the cached value until it falls inside the safety margin or expires,
// at which point a fresh token is minted from the wrapped source.
//
// The ctx is held for cancellation symmetry; the wrapped TokenSource
// may or may not honor it depending on its implementation
// (clientcredentials.Config does, via the http.Client it dialed).
func (t *Token) Token(_ context.Context) (*oauth2.Token, error) {
	t.mu.Lock()
	defer t.mu.Unlock()

	if t.cur != nil && t.cur.Expiry.Sub(t.now()) > safetyMargin {
		return t.cur, nil
	}

	fresh, err := t.src.Token()
	if err != nil {
		return nil, err
	}
	t.cur = fresh
	t.refreshes.Add(1)
	return fresh, nil
}

// RefreshCount returns the number of times a fresh token was minted —
// the value the migrator_token_refresh_total counter should report.
// Lock-free read.
func (t *Token) RefreshCount() int64 {
	return t.refreshes.Load()
}


