package migrator_test

import (
	"context"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"golang.org/x/oauth2"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
)

// fakeSource is a minimal oauth2.TokenSource that returns programmable
// tokens. Each call increments a counter so tests can assert how many
// times the cache reached for a fresh token.
type fakeSource struct {
	mu      sync.Mutex
	calls   atomic.Int64
	now     func() time.Time
	expires time.Duration // how long each minted token is valid
}

func (f *fakeSource) Token() (*oauth2.Token, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	n := f.calls.Add(1)
	exp := f.now().Add(f.expires)
	return &oauth2.Token{
		AccessToken: "tok-" + string(rune('0'+n)),
		Expiry:      exp,
	}, nil
}

func TestToken_FirstCallMintsFresh(t *testing.T) {
	src := &fakeSource{now: time.Now, expires: time.Hour}
	tok := migrator.NewToken(src)

	got, err := tok.Token(context.Background())
	require.NoError(t, err)
	require.Equal(t, "tok-1", got.AccessToken)
	require.Equal(t, int64(1), src.calls.Load())
}

func TestToken_SubsequentCallReusesCachedWhenFresh(t *testing.T) {
	src := &fakeSource{now: time.Now, expires: time.Hour}
	tok := migrator.NewToken(src)

	_, err := tok.Token(context.Background())
	require.NoError(t, err)
	got, err := tok.Token(context.Background())
	require.NoError(t, err)

	require.Equal(t, "tok-1", got.AccessToken, "cached token should be reused")
	require.Equal(t, int64(1), src.calls.Load(), "no second mint")
}

func TestToken_RefreshesWhenWithinSafetyMargin(t *testing.T) {
	now := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	clock := &mockClock{t: now}
	src := &fakeSource{now: clock.Now, expires: 60 * time.Second}

	tok := migrator.NewTokenWithClock(src, clock.Now)
	_, err := tok.Token(context.Background())
	require.NoError(t, err)

	// Advance to 31s before expiry — outside the 30s safety margin.
	clock.t = now.Add(29 * time.Second)
	_, err = tok.Token(context.Background())
	require.NoError(t, err)
	require.Equal(t, int64(1), src.calls.Load(), "still cached at t+29s")

	// Advance into the 30s window.
	clock.t = now.Add(31 * time.Second)
	got, err := tok.Token(context.Background())
	require.NoError(t, err)
	require.Equal(t, "tok-2", got.AccessToken, "should have refreshed")
	require.Equal(t, int64(2), src.calls.Load())
}

func TestToken_RefreshesWhenExpired(t *testing.T) {
	now := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	clock := &mockClock{t: now}
	src := &fakeSource{now: clock.Now, expires: 30 * time.Second}

	tok := migrator.NewTokenWithClock(src, clock.Now)
	_, err := tok.Token(context.Background())
	require.NoError(t, err)

	clock.t = now.Add(45 * time.Second) // past expiry
	got, err := tok.Token(context.Background())
	require.NoError(t, err)
	require.Equal(t, "tok-2", got.AccessToken)
	require.Equal(t, int64(2), src.calls.Load())
}

func TestToken_ConcurrentCallsDontDoubleRefresh(t *testing.T) {
	src := &fakeSource{now: time.Now, expires: time.Hour}
	tok := migrator.NewToken(src)

	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, _ = tok.Token(context.Background())
		}()
	}
	wg.Wait()

	require.Equal(t, int64(1), src.calls.Load(),
		"50 concurrent Token() calls must coalesce into one mint")
}

func TestToken_RefreshCountReflectsActualMints(t *testing.T) {
	now := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	clock := &mockClock{t: now}
	src := &fakeSource{now: clock.Now, expires: 60 * time.Second}

	tok := migrator.NewTokenWithClock(src, clock.Now)
	_, err := tok.Token(context.Background())
	require.NoError(t, err)
	require.Equal(t, int64(1), tok.RefreshCount())

	clock.t = now.Add(31 * time.Second)
	_, err = tok.Token(context.Background())
	require.NoError(t, err)
	require.Equal(t, int64(2), tok.RefreshCount())
}

type mockClock struct {
	mu sync.Mutex
	t  time.Time
}

func (m *mockClock) Now() time.Time {
	m.mu.Lock()
	defer m.mu.Unlock()
	return m.t
}



