package migrator_test

import (
	"context"
	"errors"
	"strings"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/migrator"
)

// memBackend is an in-memory migrator.KVBackend used by Cursor tests.
// Real production code passes a JetStreamKV wrapper over a NATS bucket.
type memBackend struct {
	mu sync.Mutex
	kv map[string][]byte
}

func newMemBackend() *memBackend {
	return &memBackend{kv: map[string][]byte{}}
}

func (m *memBackend) Get(_ context.Context, key string) ([]byte, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	v, ok := m.kv[key]
	if !ok {
		return nil, migrator.ErrCursorNotFound
	}
	return append([]byte(nil), v...), nil
}

func (m *memBackend) Put(_ context.Context, key string, value []byte) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.kv[key] = append([]byte(nil), value...)
	return nil
}

func TestCursor_GetReturnsZeroAndFalseOnFirstRun(t *testing.T) {
	c := migrator.NewCursor(newMemBackend())
	off, found, err := c.Get(context.Background(), "migrator-identity", "42", "users")
	require.NoError(t, err)
	require.False(t, found)
	require.Equal(t, int64(0), off)
}

func TestCursor_PutThenGetRoundTrips(t *testing.T) {
	c := migrator.NewCursor(newMemBackend())
	ctx := context.Background()

	require.NoError(t, c.Put(ctx, "migrator-identity", "42", "users", 12345))
	off, found, err := c.Get(ctx, "migrator-identity", "42", "users")
	require.NoError(t, err)
	require.True(t, found)
	require.Equal(t, int64(12345), off)
}

func TestCursor_KeysAreScopedByBinaryAndTenantAndEntity(t *testing.T) {
	be := newMemBackend()
	c := migrator.NewCursor(be)
	ctx := context.Background()

	require.NoError(t, c.Put(ctx, "migrator-identity", "42", "users", 1))
	require.NoError(t, c.Put(ctx, "migrator-org", "42", "tenants", 2))
	require.NoError(t, c.Put(ctx, "migrator-identity", "99", "users", 3))

	off1, _, _ := c.Get(ctx, "migrator-identity", "42", "users")
	off2, _, _ := c.Get(ctx, "migrator-org", "42", "tenants")
	off3, _, _ := c.Get(ctx, "migrator-identity", "99", "users")

	require.Equal(t, int64(1), off1)
	require.Equal(t, int64(2), off2)
	require.Equal(t, int64(3), off3)
