	be := newMemBackend()
	c := migrator.NewCursor(be)
	require.NoError(t, c.Put(context.Background(), "migrator-org", "42", "tenants", 12345))

	be.mu.Lock()
	defer be.mu.Unlock()
	require.Equal(t, "12345", string(be.kv["migrator-org/42/tenants"]),
		"value must be ASCII decimal so operators can `nats kv get` and read it")
}

func TestCursor_RejectsEmptyComponents(t *testing.T) {
	c := migrator.NewCursor(newMemBackend())
	ctx := context.Background()

	cases := []struct{ binary, tenant, entity string }{
		{"", "42", "users"},
		{"migrator-identity", "", "users"},
		{"migrator-identity", "42", ""},
	}
	for _, tc := range cases {
		err := c.Put(ctx, tc.binary, tc.tenant, tc.entity, 1)
		require.Errorf(t, err, "empty component (%q,%q,%q) must be rejected",
			tc.binary, tc.tenant, tc.entity)
	}
