package migrator

import (
	"context"
	"fmt"
	"time"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"
)

// Metrics holds the OTel instruments emitted by the migrator binaries.
// Names + label keys are the public contract — Grafana dashboards and
// alert rules query them. See spec §13 for the full set.
//
// All instruments are created up-front in NewMetrics so first-call
// latency in the apply loop is just a counter increment.
type Metrics struct {
	rowsPlanned     metric.Int64Counter
	rowsApplied     metric.Int64Counter
	applyDuration   metric.Float64Histogram
	lagRows         metric.Int64Gauge
	rejections      metric.Int64Counter
	tokenRefreshes  metric.Int64Counter
}

// NewMetrics creates the six instruments on the given Meter. The
// caller is responsible for wiring meter into a MeterProvider that
// exports somewhere useful (OTLP collector in production, manual
// reader in tests).
func NewMetrics(meter metric.Meter) (*Metrics, error) {
	rowsPlanned, err := meter.Int64Counter(
		"migrator_rows_planned_total",
		metric.WithDescription("Rows the migrator planned to apply (dry-run count). Labels: tenant, entity."),
	)
	if err != nil {
		return nil, fmt.Errorf("migrator: rows_planned counter: %w", err)
	}
	rowsApplied, err := meter.Int64Counter(
		"migrator_rows_applied_total",
		metric.WithDescription("Rows the migrator successfully applied. Labels: tenant, entity, result (created/upserted/skipped/errored)."),
	)
	if err != nil {
		return nil, fmt.Errorf("migrator: rows_applied counter: %w", err)
	}
	applyDuration, err := meter.Float64Histogram(
		"migrator_apply_duration_seconds",
		metric.WithDescription("Per-row apply duration. Labels: tenant, entity."),
		metric.WithUnit("s"),
	)
	if err != nil {
		return nil, fmt.Errorf("migrator: apply_duration histogram: %w", err)
	}
	lagRows, err := meter.Int64Gauge(
		"migrator_lag_rows",
		metric.WithDescription("Outstanding legacy rows not yet applied. Labels: tenant, entity. Set after each batch; cutover go/no-go is lag == 0."),
	)
	if err != nil {
		return nil, fmt.Errorf("migrator: lag_rows gauge: %w", err)
	}
	rejections, err := meter.Int64Counter(
		"migrator_rejections_total",
		metric.WithDescription("Rows skipped due to RPC errors and written to the rejection report. Labels: tenant, entity, error_code."),
	)
	if err != nil {
		return nil, fmt.Errorf("migrator: rejections counter: %w", err)
	}
	tokenRefreshes, err := meter.Int64Counter(
		"migrator_token_refresh_total",
		metric.WithDescription("Service-account access-token mints. No labels — global to the migrator process."),
	)
	if err != nil {
		return nil, fmt.Errorf("migrator: token_refresh counter: %w", err)
	}

	return &Metrics{
		rowsPlanned:    rowsPlanned,
		rowsApplied:    rowsApplied,
		applyDuration:  applyDuration,
		lagRows:        lagRows,
		rejections:     rejections,
		tokenRefreshes: tokenRefreshes,
	}, nil
}

// RowsPlanned increments the planned-rows counter for (tenant, entity).
func (m *Metrics) RowsPlanned(ctx context.Context, tenant, entity string) {
	m.rowsPlanned.Add(ctx, 1, metric.WithAttributes(
		attribute.String("tenant", tenant),
		attribute.String("entity", entity),
	))
}

// RowsApplied increments the applied-rows counter for the given
// (tenant, entity, result) triple. Result is one of
// "created" / "upserted" / "skipped" / "errored" per spec §5.6d/§9.
func (m *Metrics) RowsApplied(ctx context.Context, tenant, entity, result string) {
	m.rowsApplied.Add(ctx, 1, metric.WithAttributes(
		attribute.String("tenant", tenant),
		attribute.String("entity", entity),
		attribute.String("result", result),
	))
}

// RecordApplyDuration records the wall time for one row's apply RPC.
// Histogram unit is seconds; pass time.Duration directly.
func (m *Metrics) RecordApplyDuration(ctx context.Context, tenant, entity string, dur time.Duration) {
	m.applyDuration.Record(ctx, dur.Seconds(), metric.WithAttributes(
		attribute.String("tenant", tenant),
		attribute.String("entity", entity),
	))
}

// SetLagRows sets the gauge to n. Subsequent calls overwrite — this is
// not an additive counter. Cutover go/no-go is lag == 0.
func (m *Metrics) SetLagRows(ctx context.Context, tenant, entity string, n int64) {
	m.lagRows.Record(ctx, n, metric.WithAttributes(
		attribute.String("tenant", tenant),
		attribute.String("entity", entity),
	))
}

// RejectionsInc increments the rejections counter. errorCode is the
// gRPC status code name from the failed RPC ("INVALID_ARGUMENT",
// "PERMISSION_DENIED", "NOT_FOUND", etc.) — keep it bounded so
// cardinality doesn't explode.
func (m *Metrics) RejectionsInc(ctx context.Context, tenant, entity, errorCode string) {
	m.rejections.Add(ctx, 1, metric.WithAttributes(
		attribute.String("tenant", tenant),
		attribute.String("entity", entity),
		attribute.String("error_code", errorCode),
	))
}

// TokenRefreshInc increments the token-refresh counter. Called from
// the Token cache when a fresh service-account token is minted.
func (m *Metrics) TokenRefreshInc(ctx context.Context) {
	m.tokenRefreshes.Add(ctx, 1)
}


