	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			_ = rj.Write(migrator.RejectionEntry{
				LegacyID: "row",
				Entity:   "users",
				ErrorMsg: "msg",
			})
		}(i)
	}
	wg.Wait()
	require.NoError(t, rj.Close())

	body, err := os.ReadFile(filepath.Join(dir, "concurrent.jsonl"))
	require.NoError(t, err)
	lines := strings.Split(strings.TrimRight(string(body), "\n"), "\n")
	require.Len(t, lines, 50, "every Write must produce exactly one line")
