		require.NoErrorf(t, json.Unmarshal([]byte(line), &got),
			"line %d (%q) is not valid JSON — interleaving bug", i, line)
	}
}

func TestRejection_WriteAfterCloseReturnsError(t *testing.T) {
	dir := t.TempDir()
